/**
 * DCache module
 * author: yulesyu
 */

var cacheShareProxy = require('./CacheShareJce.js');
var proxyShareProxy = require('./ProxyShareJce.js');

/**
 * @param option
 * {
 *      DCacheServerTarget: servant, 默认值DCache.TRomProxyServer.ProxyObj
 *      moduleName: 模块名，默认值TRomNode
 *      configFile: 配置文件名字, 绝对地址
 *      proxy: 代理地址
 * }
 * @constructor
 */
function Cache(option) {
  option = option || {}
  this._DCacheServerTarget = option['proxy'] || option['DCacheServerTarget'];
  this._moduleName = option['moduleName'] || 'TRomNode'
  this._forceMaster = option['forceMaster'] === true

  // 初始化调用Taf
  this._Taf = require('@taf/taf-rpc').client;
  this._DCache = require('./ProxyProxy.js').DCache

  var configFile = option['configFile']; // 配置文件
  this._Taf.initialize(configFile);

  if(option.hasOwnProperty("keepAlive") && option.keepAlive == false){
      this._prx = this._Taf.stringToProxy(this._DCache.ProxyProxy, this._DCacheServerTarget);
  }else{
      //默认开启keep-alive
      option.keepAlive = true;
      option.heartInterval = 20000;
      this._prx = this._Taf.stringToProxy(this._DCache.ProxyProxy, this._DCacheServerTarget,  "", {keepAlive: option.keepAlive, heartInterval: option.heartInterval});
  }
  

  this._apiNames = []
  var arr = Object.keys(this._DCache.ProxyProxy.prototype)
  var that = this
  arr.forEach(function (value) {
    if (value !== 'setTimeout' && value !== 'getTimeout') {
      that._apiNames.push(value);
    }
  })

  this._apiNames.forEach(function (value) {

    that[value] = function () {
      var api = that._prx[value]
      var args = [that._moduleName].concat(Array.prototype.slice.call(arguments))

      return new Promise((res, rej) => {
        api.apply(that._prx, args).then(function (ret) {

          ret = ret['response'];
          var result = ret['arguments'] || {};

          // 查询成功
          if (ret['return'] >= 0)
            return res({ iRet: ret['return'], data: result })

          // 查询返回-6
          if (value.startsWith('getString') && ret['return'] === -6)
            return res({ iRet: -6, data: result })

          // 异常状态码
          return rej({ iRet: ret['return'], data: result })

        }, errMsg => rej({ iRet: -9999, data: errMsg })).done()
      })
    }
  })
}
module.exports = Cache
Cache.cacheShareProxy = cacheShareProxy
Cache.proxyShareProxy = proxyShareProxy